CREATE TRIGGER TR_Check_WholesalerConsistency
ON FinalHoneyProductionDetails
AFTER INSERT
AS
BEGIN
    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN FinalHoneyProductions f 
            ON i.FinalHoneyProductionId = f.FinalHoneyProductionId
        JOIN RawHoneyProductions r 
            ON i.RawHoneyProductionId = r.RawHoneyProductionId
        WHERE f.FinalHoneyProductionWholesalerId 
              <> r.RawHoneyProductionWholesalerId
    )
    BEGIN
        RAISERROR('Error: Raw Honey Wholesaler must match Final Batch Wholesaler.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END;
GO
ALTER TABLE [dbo].[FinalHoneyProductionDetails] ENABLE TRIGGER [TR_Check_WholesalerConsistency]
